unsafe fn init_interrupts_v10_3(adev:*mut amdgpu_device, pipe_id:u32, _inst:u32)->i32 { let mec=pipe_id/(*adev).gfx.mec.num_pipe_per_mec+1; let pipe=pipe_id%(*adev).gfx.mec.num_pipe_per_mec; lock_srbm(adev,mec,pipe,0,0); WREG32_SOC15!(GC,0,mmCPC_INT_CNTL,CP_INT_CNTL_RING0__TIME_STAMP_INT_ENABLE_MASK|CP_INT_CNTL_RING0__OPCODE_ERROR_INT_ENABLE_MASK); unlock_srbm(adev); 0 }
unsafe fn get_sdma_rlc_reg_offset(adev:*mut amdgpu_device, engine_id:u32, queue_id:u32)->u32 { let base=match engine_id { 0=>SOC15_REG_OFFSET!(SDMA0,0,mmSDMA0_RLC0_RB_CNTL)-mmSDMA0_RLC0_RB_CNTL, 1=>SOC15_REG_OFFSET!(SDMA0,0,mmSDMA1_RLC0_RB_CNTL)-mmSDMA0_RLC0_RB_CNTL, 2=>SOC15_REG_OFFSET!(SDMA0,0,mmSDMA2_RLC0_RB_CNTL)-mmSDMA0_RLC0_RB_CNTL, 3=>SOC15_REG_OFFSET!(SDMA0,0,mmSDMA3_RLC0_RB_CNTL)-mmSDMA0_RLC0_RB_CNTL, _=>{dev_warn!((*adev).dev,"Invalid sdma engine id (%d), using engine id 0\n",engine_id); SOC15_REG_OFFSET!(SDMA0,0,mmSDMA0_RLC0_RB_CNTL)-mmSDMA0_RLC0_RB_CNTL} }; let off=base+queue_id*(mmSDMA0_RLC1_RB_CNTL-mmSDMA0_RLC0_RB_CNTL); pr_debug!("RLC register offset for SDMA%d RLC%d: 0x%x\n",engine_id,queue_id,off); off }
#[inline] unsafe fn get_mqd(mqd:*mut core::ffi::c_void)->*mut v10_compute_mqd { mqd as *mut v10_compute_mqd }
