 let hqd=(&m.cp_mqd_base_addr_lo as *const u32) as *const u32; let base=SOC15_REG_OFFSET!(GC,0,mmCP_MQD_BASE_ADDR); for reg in base..=SOC15_REG_OFFSET!(GC,0,mmCP_HQD_PQ_WPTR_HI) { WREG32_SOC15_IP!(GC,reg,*hqd.add((reg-base) as usize)); }
