unsafe fn hqd_sdma_is_occupied_v10_3(adev:*mut amdgpu_device,mqd:*mut core::ffi::c_void)->bool { let m=&*get_sdma_mqd(mqd); let off=get_sdma_rlc_reg_offset(adev,m.sdma_engine_id,m.sdma_queue_id); RREG32!(off+mmSDMA0_RLC0_RB_CNTL)&SDMA0_RLC0_RB_CNTL__RB_ENABLE_MASK != 0 }
unsafe fn hqd_is_occupied_v10_3(adev:*mut amdgpu_device,queue_address:u64,pipe_id:u32,queue_id:u32,_inst:u32)->bool { acquire_queue(adev,pipe_id,queue_id); let act=RREG32_SOC15!(GC,0,mmCP_HQD_ACTIVE); let yes=act!=0 && lower_32_bits(queue_address>>8)==RREG32_SOC15!(GC,0,mmCP_HQD_PQ_BASE) && upper_32_bits(queue_address>>8)==RREG32_SOC15!(GC,0,mmCP_HQD_PQ_BASE_HI); release_queue(adev); yes }

