unsafe fn hiq_mqd_load_v10_3(adev:*mut amdgpu_device,mqd:*mut core::ffi::c_void,pipe_id:u32,queue_id:u32,doorbell_off:u32,_inst:u32)->i32 { let m=&*get_mqd(mqd); acquire_queue(adev,pipe_id,queue_id); let mec=pipe_id/(*adev).gfx.mec.num_pipe_per_mec+1; let pipe=pipe_id%(*adev).gfx.mec.num_pipe_per_mec; let ring=&mut (*adev).gfx.kiq[0].ring; spin_lock(&mut (*adev).gfx.kiq[0].ring_lock); let r=amdgpu_ring_alloc(ring,7); if r==0 { amdgpu_ring_write!(ring,PACKET3!(PACKET3_MAP_QUEUES,5)); amdgpu_ring_write!(ring,PACKET3_MAP_QUEUES_QUEUE_SEL!(0)|PACKET3_MAP_QUEUES_VMID!(m.cp_hqd_vmid)|PACKET3_MAP_QUEUES_QUEUE!(queue_id)|PACKET3_MAP_QUEUES_PIPE!(pipe)|PACKET3_MAP_QUEUES_ME!(mec-1)|PACKET3_MAP_QUEUES_ENGINE_SEL!(1)|PACKET3_MAP_QUEUES_NUM_QUEUES!(1)); amdgpu_ring_write!(ring,PACKET3_MAP_QUEUES_DOORBELL_OFFSET!(doorbell_off)); amdgpu_ring_write!(ring,m.cp_mqd_base_addr_lo); amdgpu_ring_write!(ring,m.cp_mqd_base_addr_hi); amdgpu_ring_write!(ring,m.cp_hqd_pq_wptr_poll_addr_lo); amdgpu_ring_write!(ring,m.cp_hqd_pq_wptr_poll_addr_hi); amdgpu_ring_commit(ring); } spin_unlock(&mut (*adev).gfx.kiq[0].ring_lock); release_queue(adev); r }

unsafe fn hqd_dump_v10_3(adev:*mut amdgpu_device,pipe_id:u32,queue_id:u32,dump:*mut *mut [[u32;2]],n_regs:*mut u32,_inst:u32)->i32 { const HQD_N_REGS:usize=56; *dump=kmalloc_objs!(*dump,HQD_N_REGS); if (*dump).is_null(){return -ENOMEM;} acquire_queue(adev,pipe_id,queue_id); let mut i=0usize; for reg in SOC15_REG_OFFSET!(GC,0,mmCP_MQD_BASE_ADDR)..=SOC15_REG_OFFSET!(GC,0,mmCP_HQD_PQ_WPTR_HI){ (**dump)[i]=[(reg<<2),RREG32_SOC15_IP!(GC,reg)]; i+=1; } release_queue(adev); *n_regs=i as u32; 0 }
