unsafe fn hqd_sdma_load_v10_3(adev:*mut amdgpu_device,mqd:*mut core::ffi::c_void,wptr:*mut u32,mm:*mut mm_struct)->i32 { let m=&mut *get_sdma_mqd(mqd); let off=get_sdma_rlc_reg_offset(adev,m.sdma_engine_id,m.sdma_queue_id); WREG32!(off+mmSDMA0_RLC0_RB_CNTL,m.sdmax_rlcx_rb_cntl&!SDMA0_RLC0_RB_CNTL__RB_ENABLE_MASK); let end=msecs_to_jiffies(2000)+jiffies; loop { if RREG32!(off+mmSDMA0_RLC0_CONTEXT_STATUS)&SDMA0_RLC0_CONTEXT_STATUS__IDLE_MASK!=0{break;} if time_after!(jiffies,end){return -ETIME;} usleep_range(500,1000); } WREG32!(off+mmSDMA0_RLC0_DOORBELL_OFFSET,m.sdmax_rlcx_doorbell_offset); WREG32!(off+mmSDMA0_RLC0_DOORBELL,REG_SET_FIELD!(m.sdmax_rlcx_doorbell,SDMA0_RLC0_DOORBELL,ENABLE,1)); WREG32!(off+mmSDMA0_RLC0_RB_RPTR,m.sdmax_rlcx_rb_rptr); WREG32!(off+mmSDMA0_RLC0_RB_RPTR_HI,m.sdmax_rlcx_rb_rptr_hi); WREG32!(off+mmSDMA0_RLC0_MINOR_PTR_UPDATE,1); let mut d=0u64; if read_user_wptr(mm,wptr as *mut u64,&mut d)!=0 {WREG32!(off+mmSDMA0_RLC0_RB_WPTR,lower_32_bits(d));WREG32!(off+mmSDMA0_RLC0_RB_WPTR_HI,upper_32_bits(d));} else {WREG32!(off+mmSDMA0_RLC0_RB_WPTR,m.sdmax_rlcx_rb_rptr);WREG32!(off+mmSDMA0_RLC0_RB_WPTR_HI,m.sdmax_rlcx_rb_rptr_hi);} WREG32!(off+mmSDMA0_RLC0_MINOR_PTR_UPDATE,0); WREG32!(off+mmSDMA0_RLC0_RB_BASE,m.sdmax_rlcx_rb_base);WREG32!(off+mmSDMA0_RLC0_RB_BASE_HI,m.sdmax_rlcx_rb_base_hi);WREG32!(off+mmSDMA0_RLC0_RB_RPTR_ADDR_LO,m.sdmax_rlcx_rb_rptr_addr_lo);WREG32!(off+mmSDMA0_RLC0_RB_RPTR_ADDR_HI,m.sdmax_rlcx_rb_rptr_addr_hi);WREG32!(off+mmSDMA0_RLC0_RB_CNTL,REG_SET_FIELD!(m.sdmax_rlcx_rb_cntl,SDMA0_RLC0_RB_CNTL,RB_ENABLE,1));0 }

